import React, { useState } from 'react';
import './Kanban.css';
import WebhookStatus from './WebhookStatus';

const Kanban = () => {
  const [tasks, setTasks] = useState([
    { id: 1, title: 'Analisar pedido', status: 'a-fazer', priority: 'alta', imei: '123456789012345', unidade: 'UNIDADE-001', prazo: '2024-03-01', observacao: 'Cliente VIP' },
    { id: 2, title: 'Separar produtos', status: 'em-andamento', priority: 'media', imei: '987654321098765', unidade: 'UNIDADE-002', prazo: '2024-03-02', observacao: 'Urgente' },
    { id: 3, title: 'Gerar etiqueta', status: 'em-andamento', priority: 'baixa', imei: '456789012345678', unidade: 'UNIDADE-003', prazo: '2024-03-03', observacao: '' },
    { id: 4, title: 'Embalar produtos', status: 'feito', priority: 'media', imei: '789012345678901', unidade: 'UNIDADE-004', prazo: '2024-02-28', observacao: 'Verificado' },
    { id: 5, title: 'Enviar para transporte', status: 'feito', priority: 'alta', imei: '345678901234567', unidade: 'UNIDADE-005', prazo: '2024-02-27', observacao: 'Enviado' }
  ]);

  const [draggedTask, setDraggedTask] = useState(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [newTask, setNewTask] = useState({
    title: '',
    imei: '',
    unidade: '',
    prazo: '',
    observacao: '',
    priority: 'media'
  });

  const columns = [
    { id: 'a-fazer', title: 'A Fazer', color: '#ff6b6b' },
    { id: 'em-andamento', title: 'Em Andamento', color: '#4ecdc4' },
    { id: 'feito', title: 'Feito', color: '#45b7d1' }
  ];

  const handleDragStart = (task) => {
    setDraggedTask(task);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDrop = (e, columnId) => {
    e.preventDefault();
    if (draggedTask) {
      const updatedTask = { ...draggedTask, status: columnId };

      // Enviar webhook se a tarefa foi movida para 'Em Andamento'
      if (columnId === 'em-andamento' && draggedTask.status !== 'em-andamento') {
        sendWebhook(updatedTask);
      }

      setTasks(tasks.map(task => 
        task.id === draggedTask.id 
          ? updatedTask
          : task
      ));
      setDraggedTask(null);
    }
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'alta': return '#ff4757';
      case 'media': return '#ffa502';
      case 'baixa': return '#2ed573';
      default: return '#747d8c';
    }
  };

  const addTask = () => {
    if (newTask.title && newTask.imei && newTask.unidade && newTask.prazo) {
      const task = {
        id: tasks.length + 1,
        title: newTask.title,
        imei: newTask.imei,
        unidade: newTask.unidade,
        prazo: newTask.prazo,
        observacao: newTask.observacao,
        status: 'a-fazer',
        priority: newTask.priority
      };
      setTasks([...tasks, task]);
      setNewTask({
        title: '',
        imei: '',
        unidade: '',
        prazo: '',
        observacao: '',
        priority: 'media'
      });
      setShowAddForm(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewTask(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const sendWebhook = async (task) => {
    try {
      const webhookUrl = 'https://default937793cd67ad44b49c7060dca68e67.67.environment.api.powerplatform.com:443/powerautomate/automations/direct/workflows/40cdd26a2f8d44ff8b9b3fd44a813490/triggers/manual/paths/invoke?api-version=1&sp=%2Ftriggers%2Fmanual%2Frun&sv=1.0&sig=yAhV8BfU_yvr7EzFDqrAVdyZuAqQ-pnYmbvagBjQO0M';

      const payload = {
        event: 'task_moved_to_in_progress',
        task: {
          id: task.id,
          title: task.title,
          imei: task.imei,
          unidade: task.unidade,
          prazo: task.prazo,
          observacao: task.observacao,
          priority: task.priority,
          status: task.status,
          timestamp: new Date().toISOString()
        }
      };

      const response = await fetch(webhookUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload)
      });

      if (response.ok) {
        console.log('Webhook enviado com sucesso:', payload);
      } else {
        console.error('Erro ao enviar webhook:', response.statusText);
      }
    } catch (error) {
      console.error('Erro ao enviar webhook:', error);
    }
  };

  const deleteTask = (taskId) => {
    setTasks(tasks.filter(task => task.id !== taskId));
  };

  return (
    <div className="kanban-container">
      <div className="kanban-header">
        <h2>Kanban de Processos</h2>
        <button className="add-task-btn" onClick={() => setShowAddForm(true)}>
          + Nova Tarefa
        </button>
      </div>

      {showAddForm && (
        <div className="add-task-modal">
          <div className="modal-content">
            <h3>Nova Tarefa</h3>
            <div className="form-group">
              <label>Título:</label>
              <input
                type="text"
                name="title"
                value={newTask.title}
                onChange={handleInputChange}
                placeholder="Digite o título da tarefa"
              />
            </div>
            <div className="form-row">
              <div className="form-group">
                <label>IMEI:</label>
                <input
                  type="text"
                  name="imei"
                  value={newTask.imei}
                  onChange={handleInputChange}
                  placeholder="123456789012345"
                />
              </div>
              <div className="form-group">
                <label>Unidade:</label>
                <input
                  type="text"
                  name="unidade"
                  value={newTask.unidade}
                  onChange={handleInputChange}
                  placeholder="UNIDADE-001"
                />
              </div>
            </div>
            <div className="form-row">
              <div className="form-group">
                <label>Prazo:</label>
                <input
                  type="date"
                  name="prazo"
                  value={newTask.prazo}
                  onChange={handleInputChange}
                />
              </div>
              <div className="form-group">
                <label>Prioridade:</label>
                <select
                  name="priority"
                  value={newTask.priority}
                  onChange={handleInputChange}
                >
                  <option value="baixa">Baixa</option>
                  <option value="media">Média</option>
                  <option value="alta">Alta</option>
                </select>
              </div>
            </div>
            <div className="form-group">
              <label>Observação:</label>
              <textarea
                name="observacao"
                value={newTask.observacao}
                onChange={handleInputChange}
                placeholder="Adicione observações..."
                rows="3"
              />
            </div>
            <div className="form-actions">
              <button className="cancel-btn" onClick={() => setShowAddForm(false)}>
                Cancelar
              </button>
              <button className="save-btn" onClick={addTask}>
                Salvar Tarefa
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="kanban-board">
        {columns.map(column => (
          <div
            key={column.id}
            className="kanban-column"
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, column.id)}
          >
            <div className="column-header" style={{ backgroundColor: column.color }}>
              <h3>{column.title}</h3>
              <span className="task-count">
                {tasks.filter(task => task.status === column.id).length}
              </span>
            </div>

            <div className="column-content">
              {tasks
                .filter(task => task.status === column.id)
                .map(task => (
                  <div
                    key={task.id}
                    className="task-card"
                    draggable
                    onDragStart={() => handleDragStart(task)}
                  >
                    <div className="task-header">
                      <span 
                        className="priority-badge"
                        style={{ backgroundColor: getPriorityColor(task.priority) }}
                      >
                        {task.priority.toUpperCase()}
                      </span>
                      <button 
                        className="delete-btn"
                        onClick={() => deleteTask(task.id)}
                      >
                        ×
                      </button>
                    </div>
                    <div className="task-content">
                      <p><strong>{task.title}</strong></p>
                      <div className="task-details">
                        <span className="detail-item">📱 {task.imei}</span>
                        <span className="detail-item">🏢 {task.unidade}</span>
                        <span className="detail-item">📅 {task.prazo}</span>
                      </div>
                      {task.observacao && (
                        <div className="task-observacao">
                          <small>📝 {task.observacao}</small>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
            </div>
          </div>
        ))}
      </div>

      <WebhookStatus />
    </div>
  );
};

export default Kanban;
